import { mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join, sep } from 'node:path'
import { expect, it, vi } from 'vitest'
import { wslGatedReaddir } from '../../../native-chat/transcript-filesystem/wsl-transcript-fs-access'
import type * as WslTranscriptFsAccess from '../../../native-chat/transcript-filesystem/wsl-transcript-fs-access'
import { readAiVaultFirstUserPrompt } from '../../prompts/session-first-user-prompt-read'
import { withFullFirstUserPromptCapture } from '../../prompts/session-scanner-first-user-prompt-capture'
import type { TranscriptMessage } from '../../transcripts/session-transcript-consumers'
import { parseOpenCodeSessionFile } from './session-scanner-opencode-parser'

vi.mock('../../../native-chat/transcript-filesystem/wsl-transcript-fs-access', async (original) => {
  const actual = await original<typeof WslTranscriptFsAccess>()
  return { ...actual, wslGatedReaddir: vi.fn(actual.wslGatedReaddir) }
})

const put = async (path: string, record: unknown): Promise<void> => {
  await mkdir(dirname(path), { recursive: true })
  await writeFile(path, JSON.stringify(record))
}

it('reads the separately stored OpenCode message parts in their recorded order', async () => {
  const root = await mkdtemp(join(tmpdir(), 'orca-opencode-json-parts-'))
  const time = 1784109600000
  try {
    const path = join(root, 'session', 'project', 'ses_saved.json')
    await put(path, {
      id: 'ses_saved',
      title: 'Build investigation',
      directory: root,
      time: { created: time, updated: time + 2 }
    })
    for (const [id, role, created, content] of [
      ['msg_user', 'user', time, undefined],
      ['msg_assistant', 'assistant', time + 1, undefined],
      ['msg_inline', 'assistant', time + 2, 'An older inline message.']
    ] as const) {
      await put(join(root, 'message', 'ses_saved', `${id}.json`), {
        id,
        sessionID: 'ses_saved',
        role,
        time: { created },
        content
      })
    }
    // MessageV2 stores parts separately; their IDs, not directory enumeration, order the text.
    for (const [messageID, id, content] of [
      ['msg_user', 'prt_02', { type: 'text', text: 'Keep the command output.' }],
      ['msg_user', 'prt_01', { type: 'text', text: 'Inspect the build failure.' }],
      ['msg_assistant', 'prt_01', { type: 'reasoning', text: 'Checking the compiler.' }],
      ['msg_assistant', 'prt_03', { type: 'text', text: 'The dependency is missing.' }],
      [
        'msg_assistant',
        'prt_02',
        {
          type: 'tool',
          tool: 'read',
          state: {
            status: 'completed',
            input: { filePath: 'build.log' },
            output: 'Missing package'
          }
        }
      ]
    ] as const) {
      await put(join(root, 'part', messageID, `${id}.json`), {
        id,
        messageID,
        sessionID: 'ses_saved',
        ...content
      })
    }
    const messages: TranscriptMessage[] = []
    const session = await withFullFirstUserPromptCapture(() =>
      parseOpenCodeSessionFile(
        { path, mtimeMs: time + 2, modifiedAt: '2026-07-15T10:00:00.002Z' },
        'linux',
        { active: true, push: (message) => messages.push(message) }
      )
    )
    expect(session?.firstUserPrompt).toBe('Inspect the build failure.\nKeep the command output.')
    expect(session?.previewMessages.map(({ role, text }) => ({ role, text }))).toEqual([
      { role: 'user', text: 'Inspect the build failure. Keep the command output.' },
      { role: 'assistant', text: 'The dependency is missing.' },
      { role: 'assistant', text: 'An older inline message.' }
    ])
    expect(messages.map(({ role, text }) => ({ role, text }))).toEqual([
      { role: 'user', text: 'Inspect the build failure.\nKeep the command output.' },
      { role: 'assistant', text: 'Checking the compiler.' },
      { role: 'tool', text: 'read: build.log' },
      { role: 'tool', text: 'Missing package' },
      { role: 'assistant', text: 'The dependency is missing.' },
      { role: 'assistant', text: 'An older inline message.' }
    ])
  } finally {
    await rm(root, { recursive: true, force: true })
  }
})

it('reads only the newest preview parts when listing and the first prompt parts on demand', async () => {
  const root = await mkdtemp(join(tmpdir(), 'orca-opencode-json-listing-'))
  const time = 1784109600000
  try {
    const path = join(root, 'session', 'project', 'ses_long.json')
    await put(path, { id: 'ses_long', directory: root, time: { created: time } })
    for (let index = 0; index < 40; index++) {
      const id = `msg_${String(index).padStart(3, '0')}`
      const role = index % 2 === 0 ? 'user' : 'assistant'
      await put(join(root, 'message', 'ses_long', `${id}.json`), {
        id,
        role,
        time: { created: time + index }
      })
      // Assistant turns here are tool-only, so listing must look past them for previews.
      await put(
        join(root, 'part', id, 'prt_01.json'),
        role === 'user'
          ? { type: 'text', text: `Prompt ${index}` }
          : { type: 'tool', tool: 'bash', state: { input: { command: 'ls' }, output: 'ok' } }
      )
    }
    const file = { path, mtimeMs: time, modifiedAt: '2026-07-15T10:00:00.000Z' }
    const summary = (session: Awaited<ReturnType<typeof parseOpenCodeSessionFile>>) => ({
      messageCount: session?.messageCount,
      previews: session?.previewMessages.map(({ text }) => text),
      truncated: session?.previewMessagesTruncated
    })
    const partReads = () =>
      vi
        .mocked(wslGatedReaddir)
        .mock.calls.filter(([directory]) => directory.includes(`${sep}part${sep}`)).length
    const full = await withFullFirstUserPromptCapture(() =>
      parseOpenCodeSessionFile(file, 'linux', { active: true, push: () => {} })
    )
    vi.mocked(wslGatedReaddir).mockClear()
    const listing = await parseOpenCodeSessionFile(file, 'linux')

    expect(summary(listing)).toEqual(summary(full))
    expect(summary(listing)).toEqual({
      messageCount: 40,
      previews: ['Prompt 30', 'Prompt 32', 'Prompt 34', 'Prompt 36', 'Prompt 38'],
      truncated: true
    })
    // The newest 12 messages hold one preview beyond the five kept.
    expect(partReads()).toBe(12)

    vi.mocked(wslGatedReaddir).mockClear()
    // The First Prompt card always sends the sessionId, which must not route legacy JSON to SQLite.
    expect(
      await readAiVaultFirstUserPrompt({ agent: 'opencode', filePath: path, sessionId: 'ses_long' })
    ).toEqual({ prompt: 'Prompt 0' })
    expect(partReads()).toBe(1)
  } finally {
    await rm(root, { recursive: true, force: true })
  }
})

import { mkdir, mkdtemp, realpath, rm, stat, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { expect, it } from 'vitest'
import { discoverOpenCodeSessions } from './sqlite/session-scanner-opencode-sqlite-discovery'
import { parseAgentSessionFileCached } from '../../parse-cache/session-scanner-parse-cache'
import { resetSessionParseCacheForTests } from '../../parse-cache/session-parse-cache-store'
import {
  flushSessionParseCachePersist,
  initSessionParseCachePersistence,
  resetSessionParseCachePersistenceForTests
} from '../../parse-cache/session-parse-cache-persistence'
import type { SessionFileCandidate } from '../../session-scanner-types'
import { SessionSearchStore } from '../../../ai-vault-search/storage/session-search-store'
import { runSessionSearchIndexPass } from '../../../ai-vault-search/indexing/session-search-index-pass'
import { registerSessionSearchIndexConsumer } from '../../../ai-vault-search/indexing/session-search-index-consumer'

it('refreshes History and search when only legacy OpenCode part files change', async () => {
  const root = await realpath(await mkdtemp(join(tmpdir(), 'orca-opencode-freshness-')))
  const storage = join(root, 'storage')
  const path = join(storage, 'session', 'project', 'ses_saved.json')
  const put = async (file: string, content: unknown): Promise<void> => {
    await mkdir(dirname(file), { recursive: true })
    await writeFile(file, JSON.stringify(content))
  }
  const cacheOptions = { filePath: join(root, 'session-parse-cache.json'), appVersion: 'test' }
  let store = new SessionSearchStore(join(root, 'search.sqlite'))
  let unregister = registerSessionSearchIndexConsumer(store)
  resetSessionParseCacheForTests()
  resetSessionParseCachePersistenceForTests()
  initSessionParseCachePersistence(cacheOptions)
  const candidate = async (): Promise<SessionFileCandidate> => {
    const discovery = await discoverOpenCodeSessions({
      storageDir: storage,
      dbPaths: [],
      limitPerAgent: 10,
      issues: []
    })
    const file = discovery.files[0]
    if (!file) {
      throw new Error('Fixture session was not discovered')
    }
    return { agent: 'opencode', file, codexHome: null }
  }
  const index = async (source: SessionFileCandidate): Promise<void> => {
    await runSessionSearchIndexPass(store, [source], {
      rows: new Map(store.files().map((row) => [row.path, row]))
    })
  }
  const matches = (query: string): unknown =>
    store.connection
      .prepare(`SELECT count(*) AS count FROM messages_fts
        JOIN messages ON messages.id = messages_fts.rowid
        JOIN sessions ON sessions.id = messages.session_row_id
        WHERE messages_fts MATCH ?`)
      .get(query)?.count
  try {
    await put(path, {
      id: 'ses_saved',
      title: 'Fixture',
      directory: root,
      time: { created: 1784109600000, updated: 1784109600000 }
    })
    for (const [id, role] of [
      ['msg_user', 'user'],
      ['msg_assistant', 'assistant']
    ]) {
      await put(join(storage, 'message', 'ses_saved', `${id}.json`), {
        id,
        role,
        sessionID: 'ses_saved',
        time: { created: 1784109600000 }
      })
    }
    const userPart = join(storage, 'part', 'msg_user', 'prt_01.json')
    const assistantPart = join(storage, 'part', 'msg_assistant', 'prt_01.json')
    await put(userPart, { id: 'prt_01', type: 'text', text: 'Summarize the build.' })
    await put(assistantPart, { id: 'prt_01', type: 'text', text: 'draftquery' })
    const before = await candidate()
    await index(before)
    expect(
      (await parseAgentSessionFileCached(before, process.platform))?.previewMessages.find(
        (message) => message.role === 'assistant'
      )?.text
    ).toBe('draftquery')
    const sessionStat = await stat(path)
    await flushSessionParseCachePersist()
    unregister()
    store.close()
    resetSessionParseCacheForTests()
    resetSessionParseCachePersistenceForTests()
    initSessionParseCachePersistence(cacheOptions)
    store = new SessionSearchStore(join(root, 'search.sqlite'))
    unregister = registerSessionSearchIndexConsumer(store)
    expect(store.coversTranscript(await candidate())).toBe(true)
    expect(matches('draftquery')).toBe(1)

    await put(assistantPart, { id: 'prt_01', type: 'text', text: 'finalquery' })
    const after = await candidate()
    expect([after.file.mtimeMs, after.file.sizeBytes]).toEqual([
      sessionStat.mtimeMs,
      sessionStat.size
    ])
    expect
      .soft(
        (await parseAgentSessionFileCached(after, process.platform))?.previewMessages.find(
          (message) => message.role === 'assistant'
        )?.text
      )
      .toBe('finalquery')
    await index(after)
    expect.soft(matches('finalquery')).toBe(1)

    // A new part revision must get a fresh retry budget even when the parent is unchanged.
    for (let attempt = 0; attempt < 3; attempt++) {
      store.setFileState(path, 'failed', after.file.mtimeMs, after.file.dependencySignature)
    }
    await put(assistantPart, { id: 'prt_01', type: 'text', text: 'recoveredquery' })
    const recovered = await candidate()
    store.setFileState(path, 'failed', recovered.file.mtimeMs, recovered.file.dependencySignature)
    expect.soft(store.files()[0]?.failCount).toBe(1)
    await index(recovered)
    expect.soft(matches('recoveredquery')).toBe(1)
  } finally {
    unregister()
    store.close()
    resetSessionParseCacheForTests()
    resetSessionParseCachePersistenceForTests()
    await rm(root, { recursive: true, force: true })
  }
})

import { mkdir, rm, stat, utimes, writeFile } from 'node:fs/promises'
import { dirname, join, sep } from 'node:path'
import { afterEach, beforeEach, expect, it, vi } from 'vitest'
import { resetSessionParseCacheForTests } from '../../ai-vault/parse-cache/session-parse-cache-store'
import {
  flushSessionParseCachePersist,
  initSessionParseCachePersistence,
  resetSessionParseCachePersistenceForTests
} from '../../ai-vault/parse-cache/session-parse-cache-persistence'
import { withFullFirstUserPromptCapture } from '../../ai-vault/prompts/session-scanner-first-user-prompt-capture'
import { scanAiVaultSessions } from '../../ai-vault/session-scanner'
import { resetTranscriptConsumersForTests } from '../../ai-vault/transcripts/session-transcript-consumers'
import * as transcriptFs from '../../native-chat/transcript-filesystem/wsl-transcript-fs-access'
import { SessionSearchDirectoryListings } from '../discovery/session-search-directory-listings'
import { SessionSearchEngine } from '../query/session-search-engine'
import { SessionSearchStore } from '../storage/session-search-store'
import { registerSessionSearchIndexConsumer } from './session-search-index-consumer'
import {
  openSessionSearchIndexerHarness,
  type SessionSearchIndexerHarness
} from './session-search-indexer-test-fixture'
import { runSessionSearchPass } from './session-search-pass'

let harness: SessionSearchIndexerHarness
let store: SessionSearchStore
let storage: string
let messages: string
let part: string

async function put(path: string, value: unknown): Promise<void> {
  await mkdir(dirname(path), { recursive: true })
  await writeFile(path, JSON.stringify(value))
}

beforeEach(async () => {
  resetSessionParseCacheForTests()
  resetSessionParseCachePersistenceForTests()
  harness = await openSessionSearchIndexerHarness('ss-opencode-read-errors')
  initSessionParseCachePersistence({
    filePath: join(harness.root, 'parse-cache.json'),
    appVersion: 'test'
  })
  storage = harness.roots.opencodeStorageDir!
  messages = join(storage, 'message', 'ses_retry')
  part = join(storage, 'part', 'msg_user', 'prt_01.json')
  store = new SessionSearchStore(harness.databasePath)
  await put(join(storage, 'session', 'project', 'ses_retry.json'), {
    id: 'ses_retry',
    title: 'Saved conversation',
    directory: harness.root,
    time: { created: 1784109600000, updated: 1784109600000 }
  })
  await put(join(messages, 'msg_user.json'), {
    id: 'msg_user',
    sessionID: 'ses_retry',
    role: 'user',
    time: { created: 1784109600000 }
  })
  await put(part, { id: 'prt_01', type: 'text', text: 'Recovered prompt' })
})

afterEach(async () => {
  vi.restoreAllMocks()
  resetTranscriptConsumersForTests()
  resetSessionParseCacheForTests()
  resetSessionParseCachePersistenceForTests()
  store.close()
  await harness.cleanup()
})

function history() {
  return withFullFirstUserPromptCapture(() =>
    scanAiVaultSessions({ ...harness.roots, unlimited: true })
  )
}

function pass(): Promise<unknown> {
  return runSessionSearchPass({
    store,
    roots: harness.roots,
    full: true,
    recentPerAgent: Number.POSITIVE_INFINITY,
    listings: new SessionSearchDirectoryListings()
  })
}

function matches(query: string): string[] {
  return harness.write((db) =>
    new SessionSearchEngine(db).search({ query }).hits.map((hit) => hit.sessionId)
  )
}

it('retries History and search after part I/O errors without a source-stat change', async () => {
  // A malformed part remains skippable while a refused read must remain retryable.
  await writeFile(join(dirname(part), 'prt_bad.json'), '{')
  const before = await stat(part)
  const read = transcriptFs.wslGatedReadFile
  let blocked = true
  let code = 'EIO'
  vi.spyOn(transcriptFs, 'wslGatedReadFile').mockImplementation(async (...args) => {
    if (args[0] === part && blocked) {
      throw Object.assign(new Error('Part read refused'), { code })
    }
    return read(...args)
  })

  await history()
  blocked = false
  expect.soft((await history()).sessions[0]?.firstUserPrompt).toBe('Recovered prompt')

  registerSessionSearchIndexConsumer(store)
  blocked = true
  code = 'EACCES'
  for (let attempt = 0; attempt < 3; attempt++) {
    await pass()
    expect(matches('Recovered')).toEqual([])
  }
  await flushSessionParseCachePersist()
  resetTranscriptConsumersForTests()
  store.close()
  resetSessionParseCacheForTests()
  resetSessionParseCachePersistenceForTests()
  initSessionParseCachePersistence({
    filePath: join(harness.root, 'parse-cache.json'),
    appVersion: 'test'
  })
  store = new SessionSearchStore(harness.databasePath)
  registerSessionSearchIndexConsumer(store)
  blocked = false
  // Search must recover on its own after reopening, before History can refresh its coverage.
  await pass()
  expect.soft(matches('Recovered')).toEqual(['ses_retry'])
  // Malformed parts do not prevent caching the complete readable transcript.
  blocked = true
  expect.soft((await history()).sessions[0]?.previewMessages[0]?.text).toBe('Recovered prompt')

  const after = await stat(part)
  expect([after.size, after.mtimeMs, after.ctimeMs]).toEqual([
    before.size,
    before.mtimeMs,
    before.ctimeMs
  ])
})

it('keeps inline sessions visible and tracks fallback parts by the safe message id', async () => {
  await rm(messages, { recursive: true })
  for (const [name, record] of [
    ['inline', { id: 'msg_inline', role: 'user', content: 'Inline prompt' }],
    ['empty_string', { id: 'msg_empty_string', role: 'assistant', content: '' }],
    ['empty_array', { id: 'msg_empty_array', role: 'assistant', content: [] }],
    ['ignored', { id: 'msg_ignored', role: 'system' }],
    ['unsafe', { id: '../escape', role: 'assistant' }],
    ['different_filename', { id: 'msg_fallback', role: ' assistant ', content: null }]
  ] as const) {
    await put(join(messages, `${name}.json`), record)
  }
  const fallback = join(storage, 'part', 'msg_fallback')
  const reply = join(fallback, 'prt_01.json')
  await put(reply, { id: 'prt_01', type: 'text', text: 'Initial reply' })
  const readdir = transcriptFs.wslGatedReaddir
  vi.spyOn(transcriptFs, 'wslGatedReaddir').mockImplementation(async (...args) => {
    if (args[0].startsWith(join(storage, 'part') + sep) && args[0] !== fallback) {
      throw Object.assign(new Error('Unused part directory refused'), { code: 'EACCES' })
    }
    return readdir(...args)
  })

  const first = await history()
  expect(first.sessions.map((session) => session.sessionId)).toEqual(['ses_retry'])
  expect(first.sessions[0]?.firstUserPrompt).toBe('Inline prompt')
  expect(first.sessions[0]?.previewMessages.map(({ text }) => text).sort()).toEqual([
    'Initial reply',
    'Inline prompt'
  ])

  const before = await stat(reply)
  await put(reply, { id: 'prt_01', type: 'text', text: 'Updated reply' })
  const later = new Date(before.mtimeMs + 4_000)
  await utimes(reply, later, later)
  expect((await history()).sessions[0]?.previewMessages.map(({ text }) => text).sort()).toEqual([
    'Inline prompt',
    'Updated reply'
  ])
})
